package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public final class AlarmDefaultsTest {
    @Test public void templateTransfersBehaviorButNeverScheduleIdentityOrAuthority(){Alarm source=new Alarm(91);source.hour=22;source.minute=48;source.date=java.time.LocalDate.parse("2026-10-30");source.enabled=true;source.label="Existing night";source.days.addAll(Set.of(1,3,5));source.volume=44;source.extraLoud=true;source.sunrise=true;source.flashlight=true;source.soundDelaySeconds=45;source.vibrationDelaySeconds=30;source.rampSeconds=90;source.smartWindow=15;source.snoozeMinutes=9;source.snoozeLimit=4;source.shortenSnoozes=true;source.backupMinutes=7;source.awakeCheck=8;source.tone="chime";source.pin=true;source.vibrate=false;source.setRoutine(new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Walk",1,20),new ChallengeRoutine.Task("Math",2))));source.scheduleError="Old schedule failure";Alarm result=new AlarmDefaults(source).create(105);assertEquals(105,result.id);assertEquals(7,result.hour);assertEquals(0,result.minute);assertFalse(result.enabled);assertEquals("A fresh start",result.label);assertTrue(result.days.isEmpty());assertNull(result.skip);assertNull(result.nap);assertNull(result.date);assertEquals("",result.scheduleError);assertEquals(44,result.volume);assertTrue(result.extraLoud);assertTrue(result.sunrise);assertTrue(result.flashlight);assertEquals(45,result.soundDelaySeconds);assertEquals(30,result.vibrationDelaySeconds);assertEquals(90,result.rampSeconds);assertEquals(15,result.smartWindow);assertEquals(9,result.snoozeMinutes);assertEquals(4,result.snoozeLimit);assertTrue(result.shortenSnoozes);assertEquals(7,result.backupMinutes);assertEquals(8,result.awakeCheck);assertEquals("chime",result.tone);assertTrue(result.pin);assertFalse(result.vibrate);assertEquals(20,result.challenges().tasks.get(0).targetSteps);assertEquals(2,result.challenges().tasks.get(1).rounds);assertEquals(22,source.hour);assertTrue(source.enabled);}
    @Test public void templateAndEveryCreatedAlarmAreIndependent(){Alarm source=new Alarm(1);source.volume=70;AlarmDefaults defaults=new AlarmDefaults(source);source.volume=90;source.tone="pulse";source.days.add(1);Alarm one=defaults.create(2),two=defaults.create(3);one.volume=20;one.days.add(6);one.setRoutine(new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Retype",5))));assertEquals(70,two.volume);assertEquals("daybreak",two.tone);assertTrue(two.days.isEmpty());assertEquals("Math",two.challenges().tasks.get(0).type);assertThrows(IllegalArgumentException.class,()->defaults.create(0));}
    @Test public void unsupportedSettingsCannotBecomeDefaults(){Alarm source=new Alarm(1);source.volume=101;assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(source));source.volume=80;source.backupMinutes=-1;assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(source));source.backupMinutes=3;source.tone="file:///private.wav";assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(source));source.tone="daybreak";source.routineInvalid=true;assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(source));}
    @Test public void missingTemplateMatchesEveryLegacyFactoryBehavior(){Alarm factory=new Alarm(1),result=new AlarmDefaults(factory).create(2);assertEquals(factory.volume,result.volume);assertEquals(factory.snoozeMinutes,result.snoozeMinutes);assertEquals(factory.smartWindow,result.smartWindow);assertEquals(factory.rampSeconds,result.rampSeconds);assertEquals(factory.backupMinutes,result.backupMinutes);assertEquals(factory.awakeCheck,result.awakeCheck);assertEquals(factory.challenge,result.challenge);assertEquals(factory.difficulty,result.difficulty);assertEquals(factory.tone,result.tone);}
}
